def tr(key, lang='fr', **kwargs):
    translations=STRINGS.get(key)
    v=translations[list(LANGUAGES).index(lang)] if translations else key
    return v.format(**kwargs) if kwargs else v

def good_name(identifier, lang='fr'):
    values=GOODS.get(identifier)
    return values[list(LANGUAGES).index(lang)] if values else identifier

